-- Performance module (performance.db)
-- Review cycles, ratings and goals.
-- Generated by Migrations/build_module_databases.py --refresh-schema;
-- foreign keys into another module's file are dropped on purpose.

CREATE TABLE performance_reviews (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            employee_id INTEGER NOT NULL,
            review_date TEXT NOT NULL,
            review_period TEXT NOT NULL,
            rating INTEGER NOT NULL CHECK (rating BETWEEN 1 AND 5),
            strengths TEXT DEFAULT '',
            improvements TEXT DEFAULT '',
            goals TEXT DEFAULT '',
            reviewer TEXT NOT NULL,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);

CREATE INDEX idx_reviews_employee
            ON performance_reviews(employee_id, review_date);

